const TIER2 = {
  moves: `semi-invulnerable, volatile-secondaries (Core Enforcer, Burning Jealousy, Alluring Voice, Spectral Thief), spread-effect, spread-contact-ko, ally-effect, unnerve-resist, unnerve-recoil, cotton-down, flower-pastel-veil, battle-bond, aftermath-innardsout, receiver-alchemy, face-guards, focus-band, berry-between-hits, aria-faint, gale-wings-gen7, assurance-own-hp, gmax-effects, darts-aim-self, received-item, into-substitute, sub-per-hit, pain-split-dynamax, face-self-hit, sleep-talk-uproar, safeguard-damaging-status, helping-hand-twice, plus Q13 (Electrify / Ion Deluge on Weather Ball and kin, Z-Moves, Max Moves)`,
  presence: `the seven presence entries (Commander, Poison Puppeteer, Dancer, the presence moves, the calling moves — Metronome, Sleep Talk, Assist, Copycat, Me First, Mirror Move, Nature Power and the rest the census lists —, the Pledges, Custap with Quick Draw or Mycelium Might), redirect-tie (the switch-in order is not an input today), settle-trace-random, settle-two-act, settle-download, the three row entries, needs-moves, unburden-start-berry, field-change, activates, gas-ends-shield (only if it does not need Q5's Neutralizing Gas tracking; Q5 is LATER)`,
  eot: `eot-landing (Future Sight / Doom Desire landing), eot-cudchew, Moody (E2), eot-overtime, eot-form-change, tr-field-side, tr-moves-state, tr-splits-prelude, and the budgets (too-many, engine-error: keep, but measure and say whether the new families push more turns into "Too many cases to follow." and how to bound it)`,
}

phase('Design')
const ARCH = [
  { key: 'tier2-moves', prompt: `TIER 2 ARCHITECT (moves phase): ${TIER2.moves}.` },
  { key: 'tier2-presence', prompt: `TIER 2 ARCHITECT (presence, calling moves, start settle, rows): ${TIER2.presence}.` },
  { key: 'tier2-eot-training', prompt: `TIER 2 ARCHITECT (end of turn, Training rollout reasons, budgets): ${TIER2.eot}.` },
  { key: 'inputs', prompt: `INPUTS ARCHITECT: the earlier-turn inputs the user chose (USER-DECISIONS Q2 "those plus more"): Stockpile layers, Last move, Item used earlier (default Unknown per Q3/Q4), type controls (Type, Second type, Added type), Infatuated by, Heal Block turns left, accuracy and evasion stages, Berry locked, Mist / Lucky Chant / Mud Sport / Water Sport toggles, and the wave-2 Bench / Replacement / Hazards controls (Q1 = R) — plus every earlier-turn input the Tier 2 architects may need (e.g. a pending Future Sight / Doom Desire with its user and turns left, the switch-in order for redirect-tie, Commander, Embargo / Telekinesis / Octolock / Nightmare / Taunt / Encore / Disable turns from earlier turns, Charge, Glaive Rush, Minimize, Tar Shot, Salt Cure, Syrup Bomb, Throat Chop, Laser Focus, Gravity / Trick Room / room turns left, weather and terrain turns left — decide which are worth a control by how often the engine needs them and how small the control can be; every control defaults to the state that makes no guessed number: either "none" with an "Assumes …" fact, or "Unknown" that keeps the narrow reason). Design: the contract fields (DoublesCarried / per-side / field input), validation (bounds, impossible combinations as input issues), the compact 2v2 Field-condition UI (grouping, show-only-when-relevant rules, 375 px, accessible names unique, facts-only labels, names not positions), reset rules, the facts each default produces, how Training fills each from public information only (tracker counts; hidden values never), and tests.` },
]
const designs = await parallel(ARCH.map(a => () =>
  agent(`${GO}\nDESIGN ONLY: write only under scripts/.cache/calc-audit/status2/design/ (${a.key}.md and ${a.key}-probes*.ts/.out).\n${CTX}\n${a.prompt}\nFor each entry: read its census-guards row and guards.md's design if any; verify the pinned behaviour with probes; design the exact model on the engine as it is now and as SPEC2 changes it (state, hooks with doubles-turn.ts function names, interactions with SPEC2's families, randomness, end of turn, E2 outcome, Training public handling, facts and exact texts), or justify keeping a narrow reason; oracle cases with ids (prefix T2M-/T2P-/T2E-/IN-), sv plus at least one other game each; tests; and the track/file ownership you propose (disjoint from SPEC2 §8.3's tables, or as additions to an existing track's own files). Return a summary of decisions, riskiest points, and anything only the user can decide.`, { label: `architect-${a.key}`, phase: 'Design' })
    .then(r => ({ key: a.key, summary: r }))))

phase('Critic')
const critic = await agent(`${GO}\nDESIGN ONLY: write only under scripts/.cache/calc-audit/status2/design/.\n${CTX}\nFour architects wrote tier2-moves.md, tier2-presence.md, tier2-eot-training.md and inputs.md. Summaries: ${JSON.stringify(designs)}\nYOU ARE THE CRITIC. Verify their mechanics with your own probes (critic2-probes*.ts/.out), resolve conflicts with SPEC2 and between the four, and write scripts/.cache/calc-audit/status2/design/ADDENDUM2.md: a paste-ready delta to SPEC2 numbered like SPEC2 (§0 decisions incl. USER-DECISIONS; §2 scope deltas: every Tier 2 entry modelled or kept with a justified exact reason; §2.4 REASONS deltas; §3 contract deltas incl. every new input; §4 algorithm; §5 UI incl. the new controls; §6 Training; §7 oracle cases; §8 the MERGED build plan — Step 0a/0b, Step 1, wave 1 tracks (SPEC2's nine plus whatever Tier 2 and the inputs add, with DISJOINT file ownership and the frozen-file rule), integration 1, wave 2 (switch-outs with the replacement), reviews, final gate; §9 tests; §10 risks incl. world growth and budgets; §11 settled points). Only list userDecisions for genuine product choices the user's answers and the house rules do not settle (expected: none).`, {
  label: 'critic', phase: 'Critic',
  schema: { type: 'object', properties: { summary: { type: 'string' }, changes: { type: 'array', items: { type: 'string' } }, userDecisions: { type: 'array', items: { type: 'string' } } }, required: ['summary', 'changes', 'userDecisions'] },
})
if (critic && critic.userDecisions && critic.userDecisions.length) {
  log('Critic raised user decisions; stopping before Step 0.')
  return { designs, critic, step0: null, step1: null }
}

const STEP_RESULT = { type: 'object', properties: {
  summary: { type: 'string' }, filesChanged: { type: 'array', items: { type: 'string' } },
  gates: { type: 'string' }, notes: { type: 'array', items: { type: 'string' } },
}, required: ['summary', 'filesChanged', 'gates', 'notes'] }

phase('Step 0')
const step0a = await agent(`${GO}\nYOU HAVE THE GO-AHEAD TO CHANGE APP CODE for Step 0a.\n${CTX}\nTHE SPEC is SPEC2.md + USER-DECISIONS.md + ADDENDUM2.md (ADDENDUM2 wins). YOU ARE STEP 0a (SPEC2 §8.1 row 0a plus ADDENDUM2 §8's Step 0a additions): write the whole contract (doubles-types.ts, types.ts, doubles-world.ts incl. every new input field and state), the new hook modules with today's code moved verbatim and stubs keeping today's behaviour, the regenerated status-table.ts (kinds unchanged) via its new generator, doubles-actions.ts REASONS deltas (new texts added; nothing that changes today's output), tests/source/status2-hooks.test.ts. Write your hook map early to scripts/.cache/calc-audit/status2/build/STEP0A.md (every hook with signature and call-site file:line) because Step 0b starts once your type files are written — write doubles-types.ts, types.ts and doubles-world.ts FIRST and note in STEP0A.md when they are done. Behaviour must not change. Gates (exact output lines in STEP0A.md): npm run check; golden-1v1 --check byte-equal; regress.mjs and app-diff.mjs over all 1264 stored cases with 0 differences, facts included (reuse scripts/.cache/calc-audit/status-eot/build/step0-run-app.ts / step0-diff-app.mjs patterns); bench within 5 % of main.`, { label: 'step0a-contract-hooks', phase: 'Step 0', schema: STEP_RESULT })

const step0b = await agent(`${GO}\nYOU HAVE THE GO-AHEAD TO CHANGE APP CODE for Step 0b.\n${CTX}\nTHE SPEC is SPEC2.md + USER-DECISIONS.md + ADDENDUM2.md (ADDENDUM2 wins). Step 0a is done: ${JSON.stringify(step0a)} (hook map scripts/.cache/calc-audit/status2/build/STEP0A.md). YOU ARE STEP 0b (SPEC2 §8.1 row 0b, §3.6, plus ADDENDUM2's Step 0b additions): the shared calculation plumbing in calculate.ts, engine-corrections.cjs, model.ts, uses-to-ko.ts, mechanics.ts, doubles-targets.ts, intimidate.ts (keyed on fields nothing sets yet, so behaviour is unchanged), tests/unit/status2-plumbing.test.ts reproducing §3.6's probe numbers. Same gates as Step 0a; write scripts/.cache/calc-audit/status2/build/STEP0B.md.`, { label: 'step0b-plumbing', phase: 'Step 0', schema: STEP_RESULT })

phase('Step 1')
const step1 = await agent(`${GO}\nYOU HAVE THE GO-AHEAD TO CHANGE APP CODE for Step 1.\n${CTX}\nTHE SPEC is SPEC2.md + USER-DECISIONS.md + ADDENDUM2.md. Steps 0a and 0b are done: ${JSON.stringify({ step0a, step0b })}\nYOU ARE STEP 1: the correctness fixes of SPEC2 §8.2 (eight rows) plus any ADDENDUM2 §8 adds to Step 1. For each: reproduce with the listed oracle cases (add them to the oracle set via a cases-status2-step1.ts wired like cases-review.ts, run the oracle side), fix, confirm, add the listed tests. Gate: Step 0's gates, except that the cases each fix changes are listed by a script and match the oracle; golden-1v1 byte-equal. Then the frozen-file rule of SPEC2 §8.2 applies. Write scripts/.cache/calc-audit/status2/build/STEP1.md.`, { label: 'step1-fixes', phase: 'Step 1', schema: STEP_RESULT })

return { designs, critic, step0a, step0b, step1 }
